#include "hip_api.h"
#include <cmath>
#include <limits>
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("gold_probe MODULE OUTPUT_DIR");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m,stream,fn[2];a.Check(a.LoadModule(&m,argv[1]),"module");a.Check(a.hipStreamCreate(&stream),"stream");a.Check(a.hipModuleGetFunction(&fn[0],m,"c32_norm_gold_A"),"A");a.Check(a.hipModuleGetFunction(&fn[1],m,"c32_norm_gold_H"),"T");
for(unsigned fixture=0;fixture<8;fixture++){std::vector<unsigned char>in(512),w(1024);std::vector<float>raw(512);for(size_t i=0;i<in.size();i++)in[i]=fixture==0?0:(i%3?32:160);for(size_t i=0;i<w.size();i++)w[i]=i%5?32:160;for(size_t i=0;i<raw.size();i++){switch(fixture){case 2:raw[i]=i%2?0.f:-0.f;break;case 3:raw[i]=50.f;break;case 4:raw[i]=std::ldexp(float(int(i%17)-8),int(i%13)-8);break;case 5:raw[i]=i%7?0.f:std::numeric_limits<float>::infinity();break;case 6:raw[i]=i%7?0.f:-std::numeric_limits<float>::infinity();break;default:raw[i]=i%2?255.9375f:256.f;}}
void *di,*dw,*dr,*doo;a.Check(a.hipMalloc(&di,in.size()),"in");a.Check(a.hipMalloc(&dw,w.size()),"w");a.Check(a.hipMalloc(&dr,raw.size()*4),"raw");a.Check(a.hipMalloc(&doo,3104*4),"out");a.Check(a.hipMemcpy(di,in.data(),in.size(),1),"upload");a.Check(a.hipMemcpy(dw,w.data(),w.size(),1),"wup");a.Check(a.hipMemcpy(dr,raw.data(),raw.size()*4,1),"rup");unsigned use_raw=fixture>=2;std::vector<unsigned>ref;
for(int side=0;side<2;side++){void*args[]={&di,&dw,&dr,&doo,&use_raw};a.Check(a.hipModuleLaunchKernel(fn[side],1,1,1,32,1,1,0,stream,args,nullptr),"launch");a.Check(a.hipStreamSynchronize(stream),"sync");std::vector<unsigned>out(3104);a.Check(a.hipMemcpy(out.data(),doo,out.size()*4,2),"read");std::ofstream(std::string(argv[2])+"/fixture"+std::to_string(fixture)+"-"+std::to_string(side)+".u32",std::ios::binary).write((char*)out.data(),out.size()*4);if(side==0)ref=out;else{size_t diff[6]={};for(size_t i=0;i<3072;i++)diff[i/512]+=out[i]!=ref[i];for(size_t i=3072;i<3104;i++)if(out[i]||ref[i])throw std::runtime_error("sum[e] lane differs");printf("C32_NORM_GOLD fixture=%u raw=%zu square=%zu sum=%zu inv=%zu normalized=%zu FP8=%zu\n",fixture,diff[0],diff[1],diff[2],diff[3],diff[4],diff[5]);for(auto d:diff)if(d)throw std::runtime_error("norm transpose contract mismatch");}}
a.hipFree(doo);a.hipFree(dr);a.hipFree(dw);a.hipFree(di);}a.hipStreamDestroy(stream);a.hipModuleUnload(m);return 0;}catch(const std::exception&e){fprintf(stderr,"C32_NORM_GOLD_FAIL %s\n",e.what());return 1;}}
